import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as s,o as a,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Grok Build Tutorial","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/grok/grok-cli.md","filePath":"products/ai-coding/grok/grok-cli.md","lastUpdated":1787048027000}'),o={name:"products/ai-coding/grok/grok-cli.md"};function d(r,e,n,l,h,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="grok-build-tutorial" tabindex="-1">Grok Build Tutorial <a class="header-anchor" href="#grok-build-tutorial" aria-label="Permalink to &quot;Grok Build Tutorial&quot;">​</a></h1><blockquote><p>This page covers Grok Build (executable <code>grok</code>) from installation through daily use. Parameter lists are in the <a href="./grok-cheatsheet.html">cheatsheet</a>, concept distinctions in the <a href="./grok-glossary.html">glossary</a>, and task recipes in the <a href="./grok-cookbook.html">cookbook</a>.</p><p>Grok Build is in beta and ships very fast (<code>latest</code> moved 1.0.3 → 1.0.5 between 2026-08-12 and 2026-08-16), so this page deliberately avoids pinning version numbers. If a command or config key does not match your machine&#39;s actual behavior, check <a href="https://x.ai/build/changelog" target="_blank" rel="noreferrer">x.ai/build/changelog</a> first.</p></blockquote><h2 id="_1-install" tabindex="-1">1. Install <a class="header-anchor" href="#_1-install" aria-label="Permalink to &quot;1. Install&quot;">​</a></h2><p>There are three official installation channels.</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-SdPMX" id="tab-fIYEG76" checked><label data-title="macOS / Linux" for="tab-fIYEG76">macOS / Linux</label><input type="radio" name="group-SdPMX" id="tab-v3ClPYU"><label data-title="Windows PowerShell" for="tab-v3ClPYU">Windows PowerShell</label><input type="radio" name="group-SdPMX" id="tab-AwSbZ6y"><label data-title="npm (cross-platform)" for="tab-AwSbZ6y">npm (cross-platform)</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://x.ai/cli/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">x.ai</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cli</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @xai-official/grok</span></span></code></pre></div></div></div><ul><li>The first two come from <a href="https://docs.x.ai/build/overview" target="_blank" rel="noreferrer">docs.x.ai/build/overview</a> and the <a href="https://github.com/xai-org/grok-build" target="_blank" rel="noreferrer">repository README</a>.</li><li>The npm channel is documented in <a href="https://docs.x.ai/build/enterprise" target="_blank" rel="noreferrer">docs.x.ai/build/enterprise</a>, which lists it as the alternative when a network policy forbids <code>curl | bash</code>. The npm package requires Node.js <code>&gt;= 20</code> and supports x64 and arm64 on macOS / Linux / Windows.</li></ul><p>Verify the install:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span></code></pre></div><p>The <a href="https://github.com/xai-org/grok-build" target="_blank" rel="noreferrer">repository README</a> also shows <code>grok --version</code> in the install snippet. The command listed in <a href="https://docs.x.ai/build/cli/reference" target="_blank" rel="noreferrer">CLI Reference</a> is <code>grok version</code>.</p><blockquote><p><strong>Naming note</strong>: a binary you build from source is called <code>xai-grok-pager</code>; official installs ship it as <code>grok</code> (the <a href="https://github.com/xai-org/grok-build" target="_blank" rel="noreferrer">README</a> says: &quot;The binary artifact is named <code>xai-grok-pager</code>; official installs ship it as <code>grok</code>.&quot;).</p></blockquote><h2 id="_2-authenticate" tabindex="-1">2. Authenticate <a class="header-anchor" href="#_2-authenticate" aria-label="Permalink to &quot;2. Authenticate&quot;">​</a></h2><p>Four methods, from <a href="https://docs.x.ai/build/enterprise" target="_blank" rel="noreferrer">docs.x.ai/build/enterprise</a>:</p><table tabindex="0"><thead><tr><th>Method</th><th>How</th><th>When to use</th></tr></thead><tbody><tr><td>Browser OIDC</td><td><code>grok login</code> (the first launch opens a browser automatically)</td><td>Local development</td></tr><tr><td>Device code</td><td><code>grok login --device-auth</code> (RFC 8628)</td><td>SSH / remote hosts / no browser</td></tr><tr><td>API key</td><td><code>export XAI_API_KEY=&quot;xai-...&quot;</code>, then run <code>grok</code></td><td>CI, containers</td></tr><tr><td>External auth provider</td><td>Configure <code>auth_provider_command</code></td><td>Enterprise SSO</td></tr></tbody></table><p>Credential resolution order (highest to lowest): <code>model.api_key</code> &gt; <code>model.env_key</code> &gt; active session token &gt; <code>XAI_API_KEY</code>.</p><p>Subscription requirements: the <a href="https://x.ai/news/grok-build-cli" target="_blank" rel="noreferrer">launch announcement</a> (2026-05-25) says &quot;Available now to all SuperGrok and X Premium Plus subscribers.&quot;, while the marketing page <a href="https://x.ai/build" target="_blank" rel="noreferrer">x.ai/build</a> currently says &quot;Available to try for Free&quot;. The <a href="https://x.ai/news/grok-4-6" target="_blank" rel="noreferrer">Grok 4.6 announcement</a> adds a time-boxed &quot;2x included usage inside Grok Build … for the first week&quot; — still no standing free-tier number. Trust the quota you actually see after logging in. Do not invent a number.</p><p>Log out with <code>grok logout</code>.</p><h2 id="_3-first-run" tabindex="-1">3. First run <a class="header-anchor" href="#_3-first-run" aria-label="Permalink to &quot;3. First run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span></span></code></pre></div><p>Launching with no arguments enters the interactive TUI (<a href="https://docs.x.ai/build/cli/reference" target="_blank" rel="noreferrer">cli/reference</a>: &quot;Running <code>grok</code> with no arguments starts the interactive TUI.&quot;).</p><p>The first prompts xAI suggests (<a href="https://docs.x.ai/build/overview" target="_blank" rel="noreferrer">overview</a>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Explain this repo.</span></span>
<span class="line"><span>@src/main.rs Walk me through this file.</span></span></code></pre></div><p><code>@</code> references a file. <strong>Run <code>grok inspect</code> right after installing</strong> — it prints everything Grok discovered in the current directory: config sources, instruction files (with token counts), skills, plugins, hooks, and MCP servers. It is the first diagnostic to reach for whenever configuration seems to have no effect.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><h2 id="_4-essential-tui-keys" tabindex="-1">4. Essential TUI keys <a class="header-anchor" href="#_4-essential-tui-keys" aria-label="Permalink to &quot;4. Essential TUI keys&quot;">​</a></h2><p>The full key table is available inside the TUI with <code>Ctrl+.</code> (<code>Ctrl+X</code> on Windows or terminals without Kitty keyboard protocol support). The subset below is enough to get started, from <a href="https://docs.x.ai/build/keyboard-shortcuts" target="_blank" rel="noreferrer">keyboard-shortcuts</a>:</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>Send</td></tr><tr><td><code>Shift+Enter</code></td><td>Newline (not recognized by the built-in terminals in VS Code / Cursor / Windsurf / Zed — use <code>Alt+Enter</code> there)</td></tr><tr><td><code>Shift+Tab</code></td><td>Cycle Normal → Plan → Auto (when available) → Always-approve</td></tr><tr><td><code>Esc</code></td><td>Interrupt the current action</td></tr><tr><td><code>Esc Esc</code></td><td>Clear the input box; open rewind when the input is empty (<a href="https://docs.x.ai/build/keyboard-shortcuts" target="_blank" rel="noreferrer">keyboard-shortcuts</a>)</td></tr><tr><td><code>Ctrl+Enter</code> / <code>Ctrl+I</code></td><td>Interject (<code>Ctrl+L</code> in VS Code-family terminals)</td></tr><tr><td><code>Ctrl+P</code> or <code>?</code></td><td>Command palette</td></tr><tr><td><code>Ctrl+T</code></td><td>Todo panel</td></tr><tr><td><code>Ctrl+B</code></td><td>Background task panel</td></tr><tr><td><code>Ctrl+G</code></td><td>Task panel</td></tr><tr><td><code>Ctrl+S</code></td><td>Session panel</td></tr><tr><td><code>Ctrl+M</code></td><td>Toggle multiline when the input is focused; pick a model when it is not</td></tr><tr><td><code>Ctrl+\\</code></td><td>Dashboard</td></tr><tr><td><code>Ctrl+O</code></td><td>Switch to always-approve</td></tr><tr><td><code>F2</code> / <code>Ctrl+,</code></td><td>Settings</td></tr><tr><td><code>Ctrl+Q</code> / <code>Ctrl+D</code></td><td>Quit (only <code>Ctrl+D</code> works in VS Code-family terminals)</td></tr></tbody></table><p>When the terminal misbehaves (copy-paste broken, keys mis-read), run <code>/terminal-setup</code> inside the TUI for a self-check; see <a href="https://docs.x.ai/build/cli/terminal-support" target="_blank" rel="noreferrer">terminal-support</a>.</p><h2 id="_5-permissions-understand-that-these-are-two-separate-things" tabindex="-1">5. Permissions: understand that these are two separate things <a class="header-anchor" href="#_5-permissions-understand-that-these-are-two-separate-things" aria-label="Permalink to &quot;5. Permissions: understand that these are two separate things&quot;">​</a></h2><p>This is the easiest part of Grok Build to get wrong. From the official <a href="https://docs.x.ai/build/features/permissions" target="_blank" rel="noreferrer">permissions</a> page:</p><blockquote><p>&quot;Permissions decide which tool calls may run. The sandbox is separate: it limits what an approved call can do on the filesystem and network.&quot;</p></blockquote><p><strong>Permissions decide whether a tool call may run at all; the sandbox decides what it can touch once it does.</strong> The two are orthogonal and can be used together.</p><p>TUI modes and headless <code>--permission-mode</code> values are <strong>two vocabularies</strong>. The TUI cycles Ask / Auto / Always-approve. CI uses Claude Code-style <code>dontAsk</code> / <code>acceptEdits</code> (see <a href="https://docs.x.ai/build/enterprise" target="_blank" rel="noreferrer">enterprise</a> and the <a href="./grok-cheatsheet.html#permissions-and-modes">cheatsheet</a>). Do not mix the two lists.</p><p>Three TUI permission modes:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Behavior</th><th>How to enter</th></tr></thead><tbody><tr><td>Ask (default)</td><td>Anything not covered by an allow rule prompts for confirmation</td><td>—</td></tr><tr><td>Auto</td><td>A classifier auto-approves safe tools; dangerous ones may still prompt (<code>deny</code> rules and hooks still apply)</td><td><code>/auto</code>, <code>Shift+Tab</code> (when the feature is enabled)</td></tr><tr><td>Always-approve</td><td>Tool calls are auto-approved (<code>deny</code> rules and <code>PreToolUse</code> hooks still apply)</td><td><code>/always-approve</code>, <code>Ctrl+O</code>, <code>Shift+Tab</code>, <code>grok --always-approve</code></td></tr></tbody></table><p>The default mode can only be set in the <strong>user-level</strong> <code>~/.grok/config.toml</code> (a project-level <code>.grok/config.toml</code> has no effect):</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">permission_mode = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;auto&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # or &quot;ask&quot; | &quot;always-approve&quot;</span></span></code></pre></div><p>Rule syntax (<code>--allow</code> / <code>--deny</code> accept the same patterns):</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rules = [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { action = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, tool = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;bash&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, pattern = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;git *&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { action = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, tool = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;read&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { action = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deny&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  tool = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;bash&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, pattern = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rm -rf *&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Three rules worth memorizing:</p><ol><li><strong><code>deny</code> always beats <code>allow</code>.</strong> The full precedence is deny &gt; ask &gt; allow (<a href="https://docs.x.ai/build/settings/reference" target="_blank" rel="noreferrer">settings/reference</a>) — it is not &quot;last one wins&quot;.</li><li>Supported filters: <code>Bash</code>, <code>Edit</code>, <code>Read</code>, <code>Grep</code>, <code>MCPTool</code>, <code>WebFetch</code>, <code>WebSearch</code>.</li><li>Clicking &quot;always allow&quot; interactively still re-prompts for dangerous patterns like <code>rm</code> or <code>git push</code>. Only explicit allow rules in config or on the CLI truly auto-approve.</li></ol><h2 id="_6-sandbox-off-by-default" tabindex="-1">6. Sandbox: off by default <a class="header-anchor" href="#_6-sandbox-off-by-default" aria-label="Permalink to &quot;6. Sandbox: off by default&quot;">​</a></h2><p>Per <a href="https://docs.x.ai/build/features/sandbox" target="_blank" rel="noreferrer">sandbox</a>: Landlock on Linux, Seatbelt on macOS, and <strong><code>off</code> by default</strong>.</p><table tabindex="0"><thead><tr><th>Profile</th><th>Read</th><th>Write</th><th>Subprocess network</th><th>Use case</th></tr></thead><tbody><tr><td><code>off</code></td><td>Unrestricted</td><td>Unrestricted</td><td>Allowed</td><td>Default, no sandbox</td></tr><tr><td><code>workspace</code></td><td>Everywhere</td><td>CWD, <code>~/.grok/</code>, temp dirs</td><td>Allowed</td><td>Normal development</td></tr><tr><td><code>devbox</code></td><td>Everywhere</td><td>Top-level dirs except <code>/data</code></td><td>Allowed</td><td>Cloud devbox</td></tr><tr><td><code>read-only</code></td><td>Everywhere</td><td>Only <code>~/.grok/</code> and temp dirs</td><td>Blocked</td><td>Code review, audit</td></tr><tr><td><code>strict</code></td><td>CWD and system paths</td><td>CWD, <code>~/.grok/</code>, temp dirs</td><td>Blocked</td><td>Untrusted repos</td></tr></tbody></table><p>Three ways to turn it on: <code>grok --sandbox workspace</code>, <code>[sandbox] profile = &quot;workspace&quot;</code>, or <code>GROK_SANDBOX=workspace</code>.</p><p>Two limitations you must know (both stated explicitly by xAI):</p><ul><li><strong>Subprocess network restrictions only apply on Linux.</strong> On macOS, the network blocking in <code>read-only</code> / <code>strict</code> is a no-op.</li><li>Built-in profiles do <strong>not</strong> permanently protect sensitive paths such as <code>~/.ssh</code>; write your own deny list:</li></ul><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ~/.grok/sandbox.toml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">profiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">my-profile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">extends = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;workspace&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">restrict_network = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">deny = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/secrets&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;**/.env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;**/*.pem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>On Linux, &quot;readable but with certain paths denied&quot; requires <code>bubblewrap</code> installed on the system.</p><h2 id="_7-plan-mode" tabindex="-1">7. Plan mode <a class="header-anchor" href="#_7-plan-mode" aria-label="Permalink to &quot;7. Plan mode&quot;">​</a></h2><p>Enter with <code>/plan [description]</code>; view with <code>/view-plan</code> (aliases <code>/show-plan</code>, <code>/plan-view</code>). Keys on the plan review screen: <code>a</code> approve, <code>s</code> request changes, <code>c</code> comment, <code>q</code> quit, <code>Tab</code> switch focus.</p><p>Two things to know (<a href="https://docs.x.ai/build/features/plan-mode" target="_blank" rel="noreferrer">plan-mode</a>):</p><ul><li>Plan mode and permission mode are <strong>independent</strong>: even under auto or always-approve, the plan review screen is not skipped.</li><li>In plan mode only the session plan file is editable, but <strong>bash can still write through redirection</strong> — it is not hard isolation. If you need hard isolation, configure the sandbox.</li></ul><h2 id="_8-session-management" tabindex="-1">8. Session management <a class="header-anchor" href="#_8-session-management" aria-label="Permalink to &quot;8. Session management&quot;">​</a></h2><p>Sessions are stored under <code>~/.grok/sessions/</code>, indexed by working directory (<a href="https://docs.x.ai/build/features/sessions" target="_blank" rel="noreferrer">sessions</a>).</p><table tabindex="0"><thead><tr><th>Goal</th><th>How</th></tr></thead><tbody><tr><td>Resume the last session</td><td><code>grok -c</code> (or <code>--continue</code>)</td></tr><tr><td>Pick a session to resume</td><td><code>grok --resume</code> (lists candidates when no ID is given)</td></tr><tr><td>Resume a specific session</td><td><code>grok --resume &lt;id&gt;</code></td></tr><tr><td>Resume from inside the TUI</td><td><code>/resume</code></td></tr><tr><td>Fork the current session</td><td><code>/fork [directive]</code>, optionally <code>--worktree</code> / <code>--no-worktree</code></td></tr><tr><td>Roll back history</td><td><code>/rewind</code>, or <code>Esc Esc</code> on an empty input</td></tr><tr><td>Compact the context</td><td><code>/compact [focus]</code>; also happens automatically</td></tr><tr><td>Check context usage</td><td><code>/context</code>, <code>/session-info</code></td></tr><tr><td>List / search / delete</td><td><code>grok sessions list</code> / <code>search</code> / <code>delete</code></td></tr><tr><td>Export</td><td><code>grok export &lt;session-id&gt; [output]</code>, <code>--clipboard</code> for the clipboard</td></tr><tr><td>Rename</td><td><code>/rename</code> (alias <code>/title</code>)</td></tr></tbody></table><p>Grabbing the session ID from headless mode:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Start the refactor&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.sessionId&#39;</span></span></code></pre></div><h2 id="_9-project-rules-agents-md" tabindex="-1">9. Project rules: AGENTS.md <a class="header-anchor" href="#_9-project-rules-agents-md" aria-label="Permalink to &quot;9. Project rules: AGENTS.md&quot;">​</a></h2><p>Grok Build&#39;s primary project-rules file is <code>AGENTS.md</code>. Loading starts with the global rules in <code>~/.grok/</code>, then walks from the repository root down to the current directory (<a href="https://docs.x.ai/build/features/project-rules" target="_blank" rel="noreferrer">project-rules</a>).</p><p>Files it reads:</p><ul><li><code>AGENTS.md</code>, <code>Agents.md</code>, <code>AGENT.md</code></li><li><code>CLAUDE.md</code>, <code>Claude.md</code>, <code>CLAUDE.local.md</code></li><li>Every <code>*.md</code> under <code>.grok/rules/</code>, plus <code>.claude/rules/</code> and <code>.cursor/rules/</code></li></ul><p>Gitignored files are skipped. For a one-off addition use <code>--rules &lt;TEXT&gt;</code>; to replace the whole system prompt use <code>--system-prompt-override &lt;TEXT&gt;</code>. <code>grok inspect</code> lists which rules files were actually loaded and each one&#39;s token count — start there when rules seem to be ignored.</p><h2 id="_10-switching-models" tabindex="-1">10. Switching models <a class="header-anchor" href="#_10-switching-models" aria-label="Permalink to &quot;10. Switching models&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grok-build-0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Refactor this module&quot;</span></span></code></pre></div><p>Inside the TUI use <code>/model</code> (alias <code>/m</code>) or <code>Ctrl+M</code>. Reasoning effort is set with <code>/effort</code> or <code>--effort &lt;LEVEL&gt;</code>.</p><p>Pointing at a self-hosted or third-party OpenAI-compatible endpoint (<a href="https://docs.x.ai/build/overview" target="_blank" rel="noreferrer">overview</a>):</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ~/.grok/config.toml (Windows: %USERPROFILE%\\.grok\\config.toml)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">my-model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;model-id&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://api.example.com/v1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Display Name&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">env_key = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;API_KEY&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">default = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-model&quot;</span></span></code></pre></div><p>After editing, confirm it was picked up with <code>grok inspect</code>, then verify with <code>grok -p &quot;Hello&quot; -m my-model</code>.</p><h2 id="_11-headless-mode" tabindex="-1">11. Headless mode <a class="header-anchor" href="#_11-headless-mode" aria-label="Permalink to &quot;11. Headless mode&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Explain this codebase&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Explain the architecture&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> streaming-json</span></span></code></pre></div><p>Common parameters (<a href="https://docs.x.ai/build/cli/headless-scripting" target="_blank" rel="noreferrer">headless-scripting</a>):</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Purpose</th></tr></thead><tbody><tr><td><code>-p, --single &lt;PROMPT&gt;</code></td><td>Send a single prompt</td></tr><tr><td><code>-s, --session-id &lt;ID&gt;</code></td><td>Create or reuse a named headless session</td></tr><tr><td><code>-r, --resume &lt;ID&gt;</code> / <code>-c, --continue</code></td><td>Resume a session</td></tr><tr><td><code>--cwd &lt;PATH&gt;</code></td><td>Set the working directory</td></tr><tr><td><code>--output-format &lt;FMT&gt;</code></td><td><code>plain</code> (human) / <code>json</code> (one object at the end) / <code>streaming-json</code> (line-delimited JSON events)</td></tr><tr><td><code>--always-approve</code></td><td>Skip confirmations</td></tr><tr><td><code>--no-alt-screen</code></td><td>Inline output instead of taking over the screen</td></tr></tbody></table><p>Headless sessions live in <code>~/.grok/sessions</code> too.</p><p><strong>Always disable auto-update in CI</strong>: pass <code>--no-auto-update</code>, or persist it in <code>~/.grok/config.toml</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cli</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auto_update = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><h2 id="_12-acp-embed-in-an-editor-or-your-own-orchestrator" tabindex="-1">12. ACP: embed in an editor or your own orchestrator <a class="header-anchor" href="#_12-acp-embed-in-an-editor-or-your-own-orchestrator" aria-label="Permalink to &quot;12. ACP: embed in an editor or your own orchestrator&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stdio</span></span></code></pre></div><p>This runs Grok as an ACP (Agent Client Protocol) agent, speaking JSON-RPC over stdin/stdout. The handshake order in the official example (<a href="https://docs.x.ai/build/cli/headless-scripting" target="_blank" rel="noreferrer">headless-scripting</a>):</p><ol><li><code>initialize</code>, passing <code>protocolVersion: 1</code> and <code>clientCapabilities</code> (<code>fs.readTextFile</code> / <code>fs.writeTextFile</code> / <code>terminal</code>)</li><li><code>authenticate</code>: choose <code>xai.api_key</code> if <code>XAI_API_KEY</code> is set, otherwise <code>cached_token</code> (with neither, the official error text is &quot;Run <code>grok login</code> first, or set XAI_API_KEY.&quot;)</li><li><code>session/new</code>, passing <code>{ cwd, mcpServers: [] }</code></li><li><code>session/prompt</code>, passing <code>prompt: [{ type: &quot;text&quot;, text: &quot;...&quot; }]</code></li></ol><p>One critical detail: <strong>the return value of <code>session/prompt</code> is only completion metadata. The assistant&#39;s actual text arrives as a stream of <code>agent_message_chunk</code> events via <code>session/update</code></strong> — reading only the return value makes it look like nothing was produced.</p><h2 id="_13-updating-and-troubleshooting" tabindex="-1">13. Updating and troubleshooting <a class="header-anchor" href="#_13-updating-and-troubleshooting" aria-label="Permalink to &quot;13. Updating and troubleshooting&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # check only</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">V</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # install a specific version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --alpha</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # switch to the alpha channel</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grok</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stable</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # switch back to stable</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Symptom</th><th>Check first</th></tr></thead><tbody><tr><td>Config / rules / MCP not taking effect</td><td><code>grok inspect</code> (see what was actually loaded)</td></tr><tr><td>A project-level config key has no effect</td><td>A project <code>.grok/config.toml</code> <strong>only supports <code>[mcp_servers]</code>, <code>[plugins]</code>, and <code>[permission]</code></strong>; every other key must go in <code>~/.grok/config.toml</code></td></tr><tr><td>MCP server will not start</td><td><code>grok mcp doctor [name]</code>; logs are at <code>~/.grok/logs/mcp/&lt;server&gt;.stderr.log</code></td></tr><tr><td>Copy-paste or keys behaving oddly</td><td><code>/terminal-setup</code></td></tr><tr><td>Web fetch tool does nothing</td><td><code>GROK_WEB_FETCH</code> defaults to <code>0</code> (off for security); enable it explicitly</td></tr><tr><td>Cannot connect from a corporate network</td><td><code>cli-chat-proxy.grok.com</code> and <code>auth.x.ai</code> must be allowed (<a href="https://docs.x.ai/build/enterprise" target="_blank" rel="noreferrer">enterprise</a>)</td></tr></tbody></table><p>Feedback goes through <code>/feedback</code> in the TUI. <strong>Do not open PRs against <a href="https://github.com/xai-org/grok-build" target="_blank" rel="noreferrer">xai-org/grok-build</a></strong> — the README states &quot;External contributions are not accepted.&quot;</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./">Grok learning map</a></li><li><a href="./grok-cookbook.html">Cookbook</a> — hooks, MCP, skills, subagents, CI recipes</li><li><a href="./grok-cheatsheet.html">Cheatsheet</a> — full commands / flags / config keys / env vars</li><li><a href="./grok-glossary.html">Glossary</a> — permissions vs. sandbox, skill vs. plugin, and other distinctions</li><li><a href="./grok-bot.html">Grok Bot</a> — cloud-computer teammates, not this CLI</li></ul>`,86)])])}const y=t(o,[["render",d]]);export{b as __pageData,y as default};
